/**
 * @ohos/dsh-tool-git — read a GitHub repository on-device without a git binary.
 *
 * HarmonyOS forbids fork/exec, so `git` can never run here and the stock
 * tool-fs-search / forge plugins that shell out to `rg` or `gh` are dead on
 * arrival. The AI half is already in place (`read` / `glob` / `grep` are the
 * pure-JS suite); what was missing is the step that puts a repository on the
 * phone. This tool does only that one step:
 *
 *   clone / snapshot → a real working tree under `repos/<slug>`
 *   pull / log / diff / status → keep it current and inspectable
 *
 * Mechanics: `isomorphic-git` (pure JavaScript; packfile parsing goes through
 * `pako`, no WebAssembly) over HTTPS, fetched through the runtime's global
 * `fetch` — which on this platform is `host/fetch-shim.cjs`, a plain
 * `node:https` implementation. Verified under `--jitless` before this tool
 * existed: 2 MB and 92 MB packfiles both clone correctly, `wasm: false`.
 *
 * Two hard limits came out of that spike and are enforced (and documented)
 * here rather than discovered by the model:
 *
 *   - MEMORY. isomorphic-git materialises the packfile and its deltas in RAM;
 *     observed RSS ≈ 100 MB + 11 × pack size. A 92 MB repo peaked at 1.1 GB,
 *     which the OS would kill on a phone. `maxPackMb` therefore aborts a clone
 *     whose pack stream exceeds the cap, and the cap is a config knob.
 *   - SHALLOW REPOS CANNOT PULL. js-git fails with an opaque TypeError when
 *     advancing a depth-1 clone, so `snapshot` results are marked read-only in
 *     the message and `pull` refuses them by name instead of crashing.
 *
 * Everything the tool writes stays inside the session workspace (`repos/`), so
 * the `workspace-write` sandbox keeps its meaning.
 */
import z from "@deepseek-ai/schemastery";
import { defineTool } from "@deepseek-ai/dsh-tools";
import { HarnessError } from "@deepseek-ai/dsh-llm";
import nodeFs, { existsSync } from "node:fs";
import { mkdir, rename, rm } from "node:fs/promises";
import { isAbsolute, join, resolve, sep } from "node:path";
import { pathToFileURL } from "node:url";
import { createHttpClient, proxyFromEnv } from "./http.js";

const name = "tool-git";
const inject = [
	"tools",
	"workingDirectory"
];

/** Where clones live, relative to the session workspace. */
const REPOS_DIR = "repos";
const DEFAULT_MAX_PACK_MB = 50;
const DEFAULT_WARN_PACK_MB = 30;

const Config = z.object({
	/** Hard ceiling for one clone's packfile stream. Aborts mid-transfer. */
	maxPackMb: z.number().default(DEFAULT_MAX_PACK_MB),
	/** Above this the result says "large repo" instead of staying quiet. */
	warnPackMb: z.number().default(DEFAULT_WARN_PACK_MB),
	/** One clone/fetch, end to end. */
	timeoutMs: z.number().default(180000),
	/** Clone retries on a transient network failure. */
	attempts: z.number().default(2),
	/** `log` entries when the caller omits `limit`. */
	defaultLogLimit: z.number().default(20),
	/** Paths listed for `diff` / `status` when the caller omits `limit`. */
	defaultPathLimit: z.number().default(60)
});

var GitError = class extends HarnessError {
	constructor(message, code) {
		super(message);
		this.name = "GitError";
		this.code = code;
	}
};

/* --------------------------------------------------------------- helpers */

/**
 * Parse `owner/name`, a clone URL, or `git@host:owner/name` into a clone URL
 * plus a stable directory slug.
 *
 * https only: `http://` would ship a repository over a plaintext channel and
 * the platform has no git binary to fall back on, and `file://` / `ssh://`
 * cannot be served by an in-process client at all.
 */
function parseRepoSpec(raw) {
	const text = String(raw === undefined || raw === null ? "" : raw).trim();
	if (text.length === 0) {
		throw new GitError("repo is required, e.g. \"isomorphic-git/isomorphic-git\"", "GIT_BAD_REPO");
	}
	let url = text;
	const scp = /^git@([^:]+):(.+)$/.exec(text);
	if (scp !== null) {
		url = `https://${scp[1]}/${scp[2]}`;
	} else if (!/^[a-z]+:\/\//i.test(text)) {
		if (!/^[\w.-]+\/[\w.-]+$/.test(text)) {
			throw new GitError(`repo must be "owner/name" or an https URL: ${text}`, "GIT_BAD_REPO");
		}
		url = `https://github.com/${text}`;
	}
	// Trailing slashes first: "repo.git/" must lose both, in that order.
	url = url.replace(/\/+$/, "").replace(/\.git$/, "").replace(/\/+$/, "");
	let parsed;
	try {
		parsed = new URL(url);
	} catch (error) {
		throw new GitError(`not a usable repository URL: ${text}`, "GIT_BAD_REPO");
	}
	if (parsed.protocol !== "https:") {
		throw new GitError(`only https repositories are supported (got ${parsed.protocol})`, "GIT_BAD_REPO");
	}
	const parts = parsed.pathname.replace(/^\/+/, "").split("/").filter((part) => part.length > 0);
	if (parts.length < 2) {
		throw new GitError(`repository URL has no owner/name: ${url}`, "GIT_BAD_REPO");
	}
	const host = parsed.hostname.toLowerCase();
	const slug = slugOf(host === "github.com" ? "" : host, parts[0], parts[1]);
	return { url, host, slug };
}

/** Filesystem-safe directory name; the host only appears when it is not GitHub. */
function slugOf(host, owner, repo) {
	const raw = `${host.length > 0 ? `${host}-` : ""}${owner}-${repo}`.toLowerCase();
	const slug = raw.replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "");
	if (slug.length === 0) {
		throw new GitError("repository name has no usable characters", "GIT_BAD_REPO");
	}
	return slug.length > 80 ? slug.substring(0, 80) : slug;
}

/** Absolute clone path, refusing anything that would leave the workspace. */
function repoTarget(workdir, slug) {
	const root = resolve(workdir);
	const repos = join(root, REPOS_DIR);
	const target = join(repos, slug);
	if (target !== root && !target.startsWith(root + sep)) {
		throw new GitError(`clone path escapes the session workspace: ${slug}`, "GIT_OUT_OF_WORKSPACE");
	}
	return target;
}

function formatBytes(bytes) {
	if (!Number.isFinite(bytes) || bytes <= 0) {
		return "0 B";
	}
	if (bytes < 1024) {
		return `${bytes} B`;
	}
	if (bytes < 1048576) {
		return `${(bytes / 1024).toFixed(1)} KB`;
	}
	return `${(bytes / 1048576).toFixed(1)} MB`;
}

/**
 * The three refusal messages that the model reads and then reasons about.
 *
 * They are functions, and tested, because on-device runs showed the wording
 * driving the conclusion: "needs more than 50 MB" was reported back to the
 * user as "refused before downloading the packfile" — the opposite of what
 * happens — and the pull/clone pair told the model to do two different things
 * with a depth-1 snapshot, leaving no legal move on the loop.
 */
function tooLargeMessage(slug, maxPackMb, countedBytes) {
	return `${slug}: packfile exceeded the ${maxPackMb} MB limit after ` +
		`${formatBytes(countedBytes)} of transfer, so the connection was aborted mid-stream and the ` +
		"partial tree was deleted; raise tool-git's maxPackMb only if the device has the RAM " +
		"(isomorphic-git holds the whole pack in memory)";
}

function existsMessage(slug) {
	return `repos/${slug} already exists; "pull" advances it if it has full history — and a depth-1 ` +
		"snapshot cannot be pulled, so pass force=true to replace it. There is no shell on this " +
		"platform, so force is the only way to delete a clone from inside the tool.";
}

/**
 * Resolve a revision the way js-git cannot.
 *
 * isomorphic-git's `GitRefManager.resolve` understands refs and raw oids but
 * NOT ancestry syntax: `HEAD~1` and `HEAD^` both throw `NotFoundError` even in
 * a full clone with 128 commits (probed locally, --jitless). The old default
 * therefore failed on every repository, and the message blamed shallow
 * history — wrong diagnosis, wrong advice. Walk the parent chain here instead,
 * so `~N` means what the model and the user expect.
 */
async function resolveRev(git, dir, rev) {
	const match = /^(.*?)(?:~(\d+))?$/.exec(String(rev).trim());
	const name = match[1].length === 0 ? "HEAD" : match[1];
	const steps = match[2] === undefined ? 0 : Number(match[2]);
	let oid = await git.resolveRef({ fs: nodeFs, dir, ref: name });
	for (let i = 0; i < steps; i++) {
		const missing = () => new GitError(
			`${rev} does not exist: ${name} has fewer than ${steps} commit` +
			`${steps === 1 ? "" : "s"} of history here (a depth-1 snapshot keeps one commit and no ancestors)`,
			"GIT_NO_HISTORY"
		);
		// A shallow clone's commit object still records its parent's oid, but the
		// parent itself is absent from the object store — so following the pointer
		// blindly yields an oid that only explodes later, inside js-git, with a
		// message that names nothing. Verify each step is actually readable.
		const parent = await git.readCommit({ fs: nodeFs, dir, oid }).then(
			(commit) => (commit.commit.parent.length === 0 ? undefined : commit.commit.parent[0]),
			() => undefined
		);
		if (parent === undefined) {
			throw missing();
		}
		const readable = await git.readCommit({ fs: nodeFs, dir, oid: parent }).then(
			() => true,
			() => false
		);
		if (!readable) {
			throw missing();
		}
		oid = parent;
	}
	return oid;
}

function shallowMessage(slug, action) {
	if (action === "diff") {
		return `repos/${slug} has only one commit, so there is nothing before it to compare against; ` +
			"pass base=<ref> and head=<ref> to compare two known revisions, or replace the clone with " +
			"full history (clone + force=true) to diff commits";
	}
	return `repos/${slug} is a depth-1 snapshot and cannot be advanced in place ` +
		"(isomorphic-git fails on shallow pulls); refresh it with \"snapshot\" + force=true, " +
		"or replace it with \"clone\" + force=true if this repository needs history";
}

/** Abbreviated object id, the way git prints it. */
function shortOid(oid) {
	const text = String(oid === undefined || oid === null ? "" : oid);
	return text.length > 7 ? text.substring(0, 7) : text;
}

/** `abc1234 2026-11-20 message…` — one line per commit. */
function formatLogLines(commits) {
	const out = [];
	for (const entry of commits) {
		const commit = entry.commit === undefined ? {} : entry.commit;
		const when = typeof commit.committer === "object" && commit.committer !== null &&
			typeof commit.committer.timestamp === "number"
			? new Date(commit.committer.timestamp * 1000).toISOString().substring(0, 10)
			: "";
		const subject = String(commit.message === undefined ? "" : commit.message).split("\n")[0].trim();
		const parts = [shortOid(entry.oid)];
		if (when.length > 0) {
			parts.push(when);
		}
		if (subject.length > 0) {
			parts.push(subject.length > 90 ? `${subject.substring(0, 90)}…` : subject);
		}
		out.push(parts.join(" "));
	}
	return out;
}

/** `A path` / `M path` / `D path` rows for a diff walk. */
function formatDiffLines(rows) {
	const out = [];
	for (const row of rows) {
		out.push(`${row.type} ${row.path}`);
	}
	return out;
}

/** Counts plus the first `limit` paths, so a huge workdir cannot flood the turn. */
function formatStatusSummary(rows, limit) {
	let added = 0;
	let modified = 0;
	let deleted = 0;
	const lines = [];
	for (const row of rows) {
		if (row.type === "A") {
			added++;
		} else if (row.type === "D") {
			deleted++;
		} else {
			modified++;
		}
		if (lines.length < limit) {
			lines.push(`${row.type} ${row.path}`);
		}
	}
	return { added, modified, deleted, lines };
}

/** Network hiccups js-git does not retry itself. */
function isTransient(error) {
	const code = String(error && error.code !== undefined ? error.code : "");
	const message = String(error && error.message !== undefined ? error.message : error);
	return /ECONNRESET|ETIMEDOUT|EAI_AGAIN|ENOTFOUND|EPIPE|socket hang up|network|fetch failed/i.test(`${code} ${message}`) ||
		/\bHTTP 5\d\d\b/.test(message) || /\bstatus(Code)?[ :=]+5\d\d\b/.test(message);
}

/* ------------------------------------------------------------ dependencies */

let cachedGit = null;
let cachedError = null;

/**
 * Load isomorphic-git from the payload's node_modules.
 *
 * The profile tree is copied into `$DSH_HOME/profiles/ohos` at boot, so a
 * relative import would resolve against dsh-home and never find the package.
 * `bootstrap.cjs` therefore exports the payload root, and that absolute path is
 * tried first; the bare specifiers stay as a fallback for anyone who installs
 * the package into the profile itself.
 *
 * The CJS entries are preferred because the package declares `type: module`
 * and its ESM build assumes a bundler; `import()` of `index.cjs` returns
 * `module.exports` under `default`.
 *
 * The HTTP client is ours (`./http.js`), not `isomorphic-git/http/web`: see
 * that file for why (byte accounting, mid-transfer abort, no fetch coupling).
 */
async function loadGit() {
	if (cachedGit !== null) {
		return cachedGit;
	}
	if (cachedError !== null) {
		throw cachedError;
	}
	const candidates = [];
	const root = process.env.DSH_PAYLOAD_ROOT;
	if (typeof root === "string" && root.length > 0) {
		const pkg = join(root, "node_modules", "isomorphic-git");
		candidates.push(pathToFileURL(join(pkg, "index.cjs")).href);
		candidates.push(pathToFileURL(join(pkg, "index.js")).href);
	}
	candidates.push("isomorphic-git");
	let last = null;
	for (const specifier of candidates) {
		try {
			const module = await import(specifier);
			const git = module.default !== undefined && module.default !== null ? module.default : module;
			if (typeof git.clone !== "function") {
				last = new Error(`${specifier} does not export clone()`);
				continue;
			}
			cachedGit = git;
			return cachedGit;
		} catch (error) {
			last = error;
		}
	}
	cachedError = new GitError(
		`isomorphic-git is not available in this payload (${last === null ? "no candidate loaded" : last.message})`,
		"GIT_UNAVAILABLE"
	);
	throw cachedError;
}

async function withTimeout(promise, ms, label) {
	let timer = null;
	const guard = new Promise((_resolve, reject) => {
		timer = setTimeout(() => reject(new GitError(`${label} timed out after ${Math.round(ms / 1000)}s`, "GIT_TIMEOUT")), ms);
	});
	try {
		return await Promise.race([promise, guard]);
	} finally {
		if (timer !== null) {
			clearTimeout(timer);
		}
	}
}

/** Run `work` up to `attempts` times, retrying only transient failures. */
async function withRetry(work, attempts) {
	let last = null;
	for (let attempt = 1; attempt <= attempts; attempt++) {
		try {
			return await work();
		} catch (error) {
			last = error;
			if (attempt >= attempts || !isTransient(error)) {
				throw error;
			}
			await new Promise((done) => setTimeout(done, 1500 * attempt));
		}
	}
	throw last;
}

/* ---------------------------------------------------------------- actions */

/** Resolve the session working directory exactly like the stock tools do. */
async function resolveWorkdir(ctx, exec) {
	return exec.agent === undefined ? process.cwd() : await ctx.workingDirectory.ensure(exec.agent, exec.signal);
}

/**
 * One transfer's client: counts bytes as they stream and aborts over the cap.
 *
 * The whole transfer (info/refs plus the packfile) shares the budget, with 1 MB
 * of headroom so the tiny discovery request cannot eat into it. isomorphic-git
 * keeps the packfile and its deltas in memory, so the cap is a memory guard,
 * not a disk one.
 */
function transferClient(caps, slug) {
	// ArkTS reads the device's system proxy and passes it down; without that,
	// Node would go direct and a proxied device could never clone.
	const { proxy } = proxyFromEnv(process.env);
	const client = createHttpClient({
		limitBytes: caps.maxPackMb * 1048576 + 1048576,
		timeoutMs: caps.timeoutMs,
		proxy,
		// The message has to say the transfer was *aborted*, not that the repo was
		// measured beforehand: this fires mid-stream, and a model reading
		// "needs more than 50 MB" concluded we had pre-checked the size and
		// reported "no pack bytes were downloaded". We cannot know the size before
		// asking, so describe what actually happened and how far it got.
		tooLarge: () => new GitError(
			tooLargeMessage(slug, caps.maxPackMb, client.bytes()),
			"GIT_TOO_LARGE"
		)
	});
	return client;
}

async function cloneInto(ctx, exec, spec, input, caps, depth) {
	const git = await loadGit();
	const workdir = await resolveWorkdir(ctx, exec);
	const dir = repoTarget(workdir, spec.slug);
	const replacing = existsSync(dir);
	if (replacing && input.force !== true) {
		throw new GitError(existsMessage(spec.slug), "GIT_EXISTS");
	}
	await mkdir(join(workdir, REPOS_DIR), { recursive: true });
	// With force, clone into a sibling directory and only swap once the transfer
	// succeeded. Deleting first costs the user their only copy when GitHub times
	// out — which it does here (observed on device: the first attempt timed out
	// and the repository was simply gone, so log/diff said "not cloned yet").
	const staging = replacing ? join(workdir, REPOS_DIR, `.${spec.slug}.incoming`) : dir;
	if (replacing) {
		await rm(staging, { recursive: true, force: true });
	}
	const client = transferClient(caps, spec.slug);
	const started = Date.now();
	try {
		await withRetry(() => withTimeout(git.clone({
			fs: nodeFs,
			http: client,
			dir: staging,
			url: spec.url,
			depth,
			singleBranch: true,
			ref: input.ref
		}), caps.timeoutMs, `clone ${spec.slug}`), caps.attempts);
	} catch (error) {
		// A half-written tree would shadow the next attempt. The previous copy is
		// untouched: it is still at `dir`, and staging is what gets removed.
		await rm(staging, { recursive: true, force: true });
		throw error;
	}
	if (replacing) {
		await rm(dir, { recursive: true, force: true });
		await rename(staging, dir);
	}
	const seconds = ((Date.now() - started) / 1000).toFixed(1);
	const bytes = client.bytes();
	const lines = [
		`path: ${REPOS_DIR}/${spec.slug}`,
		`source: ${spec.url}`,
		`transfer: ${formatBytes(bytes)} in ${seconds}s${depth === 1 ? " (depth 1)" : ""}`
	];
	if (bytes > caps.warnPackMb * 1048576) {
		lines.push(`warning: this is a large repository for a phone; keep queries narrow (glob/grep) rather than reading broadly`);
	}
	if (depth === 1) {
		lines.push("note: a depth-1 snapshot cannot be pulled; re-run snapshot to refresh it");
	}
	return {
		ok: true,
		summary: `${depth === 1 ? "snapshot" : "cloned"} ${spec.slug} (${formatBytes(bytes)}, ${seconds}s)`,
		lines
	};
}

async function pullRepo(ctx, exec, spec, caps) {
	const git = await loadGit();
	const workdir = await resolveWorkdir(ctx, exec);
	const dir = repoTarget(workdir, spec.slug);
	if (!existsSync(dir)) {
		throw new GitError(`repos/${spec.slug} is not cloned yet; use action "clone" or "snapshot"`, "GIT_NOT_CLONED");
	}
	if (existsSync(join(dir, ".git", "shallow"))) {
		throw new GitError(shallowMessage(spec.slug, "pull"), "GIT_SHALLOW");
	}
	const client = transferClient(caps, spec.slug);
	const started = Date.now();
	const result = await withRetry(() => withTimeout(git.pull({
		fs: nodeFs,
		http: client,
		dir,
		singleBranch: true,
		fastForwardOnly: true,
		author: { name: "dsh", email: "dsh@localhost" }
	}), caps.timeoutMs, `pull ${spec.slug}`), caps.attempts);
	const seconds = ((Date.now() - started) / 1000).toFixed(1);
	const head = result === undefined || result === null || result.oid === undefined ? "" : ` → ${shortOid(result.oid)}`;
	return {
		ok: true,
		summary: `pulled ${spec.slug} in ${seconds}s${head}`,
		lines: [`path: ${REPOS_DIR}/${spec.slug}${head}`, `transfer: ${formatBytes(client.bytes())}`]
	};
}

async function logRepo(ctx, exec, spec, input, caps) {
	const git = await loadGit();
	const workdir = await resolveWorkdir(ctx, exec);
	const dir = repoTarget(workdir, spec.slug);
	if (!existsSync(dir)) {
		throw new GitError(`repos/${spec.slug} is not cloned yet; use action "clone" or "snapshot"`, "GIT_NOT_CLONED");
	}
	const limit = typeof input.limit === "number" && input.limit > 0 ? Math.min(input.limit, 200) : caps.defaultLogLimit;
	const commits = await git.log({ fs: nodeFs, dir, depth: limit, ref: input.ref });
	const lines = formatLogLines(commits);
	return {
		ok: true,
		summary: `${commits.length} commit${commits.length === 1 ? "" : "s"} in ${spec.slug}`,
		lines
	};
}

async function diffRepo(ctx, exec, spec, input, caps) {
	const git = await loadGit();
	const workdir = await resolveWorkdir(ctx, exec);
	const dir = repoTarget(workdir, spec.slug);
	if (!existsSync(dir)) {
		throw new GitError(`repos/${spec.slug} is not cloned yet; use action "clone" or "snapshot"`, "GIT_NOT_CLONED");
	}
	const base = input.base === undefined ? "HEAD~1" : input.base;
	const head = input.head === undefined ? "HEAD" : input.head;
	// No shallow pre-check: `~N` is resolved from the parent chain, so a
	// depth-1 snapshot fails here for the honest reason (no parent commit)
	// and a full clone works — which the previous version got backwards.
	const baseOid = await resolveRev(git, dir, base);
	const headOid = await resolveRev(git, dir, head);
	const rows = [];
	await git.walk({
		fs: nodeFs,
		dir,
		trees: [git.TREE({ ref: baseOid }), git.TREE({ ref: headOid })],
		map: async (filepath, entries) => {
			if (filepath === "." || entries.length < 2) {
				return undefined;
			}
			const [from, to] = entries;
			const fromType = await from.type();
			const toType = await to.type();
			if (fromType === "tree" || toType === "tree") {
				return undefined;
			}
			const fromOid = fromType === "blob" ? await from.oid() : "";
			const toOid = toType === "blob" ? await to.oid() : "";
			if (fromOid === toOid) {
				return undefined;
			}
			rows.push({ type: fromOid === "" ? "A" : toOid === "" ? "D" : "M", path: filepath });
			return undefined;
		}
	});
	const limit = typeof input.limit === "number" && input.limit > 0 ? Math.min(input.limit, 500) : caps.defaultPathLimit;
	const lines = formatDiffLines(rows.slice(0, limit));
	if (rows.length > limit) {
		lines.push(`… ${rows.length - limit} more changed paths`);
	}
	return {
		ok: true,
		summary: rows.length === 0 ? `${base}..${head} has no changes` : `${rows.length} path${rows.length === 1 ? "" : "s"} changed in ${base}..${head}`,
		lines: lines.length === 0 ? [`no changes between ${base} and ${head}`] : lines
	};
}

async function statusRepo(ctx, exec, spec, input, caps) {
	const git = await loadGit();
	const workdir = await resolveWorkdir(ctx, exec);
	const dir = repoTarget(workdir, spec.slug);
	if (!existsSync(dir)) {
		throw new GitError(`repos/${spec.slug} is not cloned yet; use action "clone" or "snapshot"`, "GIT_NOT_CLONED");
	}
	const limit = typeof input.limit === "number" && input.limit > 0 ? Math.min(input.limit, 500) : caps.defaultPathLimit;
	const matrix = await git.statusMatrix({ fs: nodeFs, dir });
	const rows = [];
	for (const row of matrix) {
		const [, head, workdirState, stage] = row;
		if (head === 1 && workdirState === 1 && stage === 1) {
			continue;
		}
		const type = head === 0 ? "A" : workdirState === 0 ? "D" : "M";
		rows.push({ type, path: row[0] });
	}
	const summary = formatStatusSummary(rows, limit);
	return {
		ok: true,
		summary: rows.length === 0
			? `${spec.slug} is clean (${matrix.length} paths)`
			: `${spec.slug}: ${summary.added} added, ${summary.modified} modified, ${summary.deleted} deleted`,
		lines: summary.lines.length === 0 ? [`working tree clean (${matrix.length} paths)`] : summary.lines
	};
}

/** Validate the model's arguments before touching the filesystem. */
function parseArgs(args) {
	const action = String(args.action === undefined ? "" : args.action).trim();
	const allowed = ["clone", "snapshot", "pull", "log", "diff", "status"];
	if (!allowed.includes(action)) {
		throw new GitError(`unknown action "${action}"; use one of ${allowed.join(", ")}`, "GIT_BAD_ACTION");
	}
	const repo = String(args.repo === undefined ? "" : args.repo).trim();
	if (repo.length === 0) {
		throw new GitError("repo is required, e.g. \"isomorphic-git/isomorphic-git\"", "GIT_BAD_REPO");
	}
	const input = { action, repo };
	if (typeof args.ref === "string" && args.ref.length > 0) {
		input.ref = args.ref;
	}
	if (typeof args.base === "string" && args.base.length > 0) {
		input.base = args.base;
	}
	if (typeof args.head === "string" && args.head.length > 0) {
		input.head = args.head;
	}
	if (typeof args.limit === "number" && Number.isFinite(args.limit) && args.limit > 0) {
		input.limit = Math.floor(args.limit);
	}
	if (args.force === true) {
		input.force = true;
	}
	return input;
}

/* ------------------------------------------------------------------ plugin */

function applyGitTool(ctx, caps) {
	// No systemPrompt section: dsh has no TOOL_GIT order constant to anchor it
	// against (getSectionOrder returns undefined, and the section API rejects a
	// non-finite order — that is exactly how this plugin first failed to mount).
	// The tool description carries the "no git binary; clone then glob/grep/read"
	// guidance instead, and it is visible exactly when the tool is.
	const tool = defineTool({
		name: "git",
		description:
			"Fetch a GitHub repository into the session workspace and inspect it, in-process over HTTPS (no git binary, no shell). " +
			"clone keeps full history (pull works later); snapshot is a depth-1 read-only copy for analysis. " +
			"log/diff/status read a repository that is already cloned. Repositories land under repos/<owner>-<name>.",
		parameters: {
			action: {
				type: "string",
				required: true,
				description: "clone | snapshot | pull | log | diff | status"
			},
			repo: {
				type: "string",
				required: true,
				description: "Repository as \"owner/name\" or an https clone URL, e.g. \"microsoft/vscode\"."
			},
			ref: {
				type: "string",
				description: "Branch or tag for clone/snapshot/log (default: the repository's default branch)."
			},
			base: {
				type: "string",
				description: "diff: the older side (default HEAD~1)."
			},
			head: {
				type: "string",
				description: "diff: the newer side (default HEAD)."
			},
			limit: {
				type: "number",
				description: "log: how many commits (default 20). diff/status: how many paths to list."
			},
			force: {
				type: "boolean",
				description: "clone/snapshot: replace an existing repos/<slug> instead of refusing. This is the only way to reset a depth-1 snapshot to full history on device (there is no shell, so no rm)."
			}
		},
		timeoutMs: caps.timeoutMs + 15000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					ok: {
						type: "boolean",
						required: true
					},
					summary: {
						type: "string",
						required: true
					},
					lines: {
						type: "array",
						items: { type: "string" }
					}
				}
			},
			render: (_args, value) => [{
				type: "text",
				text: [value.summary].concat(value.lines === undefined ? [] : value.lines).join("\n")
			}]
		},
		async execute(args, exec) {
			const input = parseArgs(args);
			const spec = parseRepoSpec(input.repo);
			if (input.action === "clone") {
				return await cloneInto(ctx, exec, spec, input, caps, undefined);
			}
			if (input.action === "snapshot") {
				return await cloneInto(ctx, exec, spec, input, caps, 1);
			}
			if (input.action === "pull") {
				return await pullRepo(ctx, exec, spec, caps);
			}
			if (input.action === "log") {
				return await logRepo(ctx, exec, spec, input, caps);
			}
			if (input.action === "diff") {
				return await diffRepo(ctx, exec, spec, input, caps);
			}
			return await statusRepo(ctx, exec, spec, input, caps);
		}
	});
	ctx.tools.register(tool);
}

/** Register the git tool (§L2 of GAP-ANALYSIS: pure JS, no subprocess). */
function apply(ctx, config) {
	const resolved = config === undefined ? Config() : config;
	applyGitTool(ctx, {
		maxPackMb: resolved.maxPackMb,
		warnPackMb: resolved.warnPackMb,
		timeoutMs: resolved.timeoutMs,
		attempts: Math.max(1, resolved.attempts),
		defaultLogLimit: resolved.defaultLogLimit,
		defaultPathLimit: resolved.defaultPathLimit
	});
}

export {
	Config,
	GitError,
	REPOS_DIR,
	apply,
	formatBytes,
	formatDiffLines,
	formatLogLines,
	formatStatusSummary,
	existsMessage,
	inject,
	isTransient,
	name,
	parseArgs,
	parseRepoSpec,
	repoTarget,
	resolveRev,
	shallowMessage,
	shortOid,
	slugOf,
	tooLargeMessage
};
